import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"Applications","description":"","frontmatter":{},"headers":[],"relativePath":"guide/applications.md","filePath":"guide/applications.md"}'),n={name:"guide/applications.md"};function r(o,e,h,l,p,d){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications&quot;">​</a></h1><p>An application runs from a container image or from a GitHub, GitLab or Bitbucket repository that Orbit builds on your server.</p><h2 id="deploying" tabindex="-1">Deploying <a class="header-anchor" href="#deploying" aria-label="Permalink to &quot;Deploying {#deploying}&quot;">​</a></h2><ul><li>A deployment waits up to 3 minutes for the application&#39;s health check and up to a minute for its certificate. Set <code>ORBIT_HEALTH_TIMEOUT</code> and <code>ORBIT_CERTIFICATE_TIMEOUT</code> (for example <code>5m</code>) in <code>orbit.service</code> to change either.</li><li>An application that exits right after starting (a failed migration, a missing variable) fails saying that it stopped right after starting, with its exit code and its last lines, instead of as a health check that never answered.</li><li><strong>Rollbacks</strong> put a previous deployment back, with the resources the application has now.</li></ul><h2 id="health-check" tabindex="-1">Health check <a class="header-anchor" href="#health-check" aria-label="Permalink to &quot;Health check {#health-check}&quot;">​</a></h2><p>Open a web application&#39;s <strong>Settings → Health check</strong> to choose an <strong>HTTP path</strong>, such as <code>/api/health</code>, or <strong>Port accepting connections</strong>. Workers and jobs have no port and do not show this block. A path must start with <code>/</code>, contain no spaces and be at most 200 characters.</p><p>An instance receives traffic only after its HTTP path answers with a <code>2xx</code> or <code>3xx</code> within 3 seconds. Without an HTTP path, the readiness check only requires a connection to its port. The deployment waits for the instances to pass this check before switching traffic.</p><p><strong>Save for next deploy</strong> stores the setting; existing instances keep their current probe until another deployment. <strong>Save and redeploy</strong> applies it now, using the current deployment&#39;s image without rebuilding or following a newer commit or image tag. If redeployment fails, the setting stays saved and the previous deployment keeps serving.</p><p><a href="./uptime#check">Uptime checks</a> use the saved path on their next check, or <code>/</code> when using a port check. These checks reach the public address once a minute; they have their own timeout and success criteria.</p><h2 id="domains" tabindex="-1">Addresses and domains <a class="header-anchor" href="#domains" aria-label="Permalink to &quot;Addresses and domains {#domains}&quot;">​</a></h2><ul><li><p><strong>Generated addresses</strong> use sslip.io: <code>&lt;service&gt;-&lt;project&gt;.&lt;server-ip-with-dashes&gt;.sslip.io</code> in production, with the environment&#39;s name before the project&#39;s elsewhere. They work as soon as the server&#39;s ports 80 and 443 are reachable from the internet. Let&#39;s Encrypt issues their certificates over HTTP; until it does, the address answers over HTTP.</p></li><li><p><strong>Custom domains</strong> need a DNS record at your provider:</p><ul><li>an <code>A</code> record to the server&#39;s IPv4 for a root domain (<code>example.com</code>);</li><li>a <code>CNAME</code> to the generated address for anything under it (<code>www.example.com</code>).</li></ul><p>With more than one <a href="./servers#entry">server receiving traffic</a>, every domain needs an <code>A</code> record for each of them instead, and the domain&#39;s page lists them.</p><p>Orbit checks every 30 seconds and routes the domain once the record points to the server. With <a href="./cloudflare">Cloudflare connected</a>, Orbit creates the records itself for domains in your zones. Turn off proxying (Cloudflare&#39;s orange cloud) until the certificate is issued: Orbit compares the resolved address with the server&#39;s, and Let&#39;s Encrypt validates over HTTP.</p></li></ul><h2 id="variables" tabindex="-1">Variables and secrets <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables and secrets {#variables}&quot;">​</a></h2><p>Variables apply on the next deployment. Secrets are sealed at rest and never shown again after you save them. Connecting a database adds a reference such as <code>DATABASE_URL</code>, whose value Orbit fills in at deploy time.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs {#logs}&quot;">​</a></h2><p>An application&#39;s output appears under <strong>Logs</strong> within a couple of seconds. Orbit keeps the last 1,000 lines of each service. Values of secret variables and common credential patterns are replaced with <code>••••••••</code> before anything is stored. Older output is still on the server, until Kubernetes rotates it away:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">environmen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">servic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal {#terminal}&quot;">​</a></h2><p><strong>Terminal</strong> on a service&#39;s page opens a shell inside one of its running instances, through Kubernetes, without SSH or <code>kubectl</code>. Pick the instance, open it and work as you would in any terminal: line editing, colours, copy and paste and resizing all work. Workers and jobs have the same tab; a job&#39;s instance exists only while a run is in progress.</p><ul><li><strong>Who:</strong> developers, admins and owners. Viewers see the tab but cannot open a shell. API tokens cannot open terminals; only a signed-in member can.</li><li><strong>Images without a shell:</strong> distroless images and those built from scratch have nothing to run. Orbit attaches a temporary debug container with busybox that shares the instance&#39;s processes, so <code>ps</code>, <code>/proc</code> and the network are the application&#39;s. It stops when the terminal closes.</li><li><strong>When it closes:</strong> after 15 minutes without input, when you sign out, when your role in the workspace changes, or when the instance stops.</li><li><strong>What is recorded:</strong> the activity records who opened and closed which instance and when. Keystrokes and output are never recorded, since they may hold secrets.</li></ul><p>The same shell by hand, on the server:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">environmen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">instanc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span></span></code></pre></div><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources {#resources}&quot;">​</a></h2><p>An application&#39;s memory, CPU and instances change from its Settings, always after a preview.</p><ul><li><strong>The preview</strong> shows what the change reserves on the server against its capacity. It counts 1 GB and 250m CPU for the runtime and everything else placed there, warns when builds lose their room or the new limit is below what the application used in the last 24 hours, and says that several instances on one server are not high availability.</li><li><strong>Applying:</strong> Orbit replaces the instances one at a time. When there is no room for a second instance, it stops the running one first, and the preview says so as downtime. If the new instances do not become ready, Orbit puts the previous values back.</li></ul><h3 id="out-of-memory" tabindex="-1">Out of memory <a class="header-anchor" href="#out-of-memory" aria-label="Permalink to &quot;Out of memory {#out-of-memory}&quot;">​</a></h3><p>An application killed for exceeding its memory limit twice within 30 minutes gets an <strong>incident</strong> and shows as degraded. The incident shows the restarts, the memory chart with the limit, the incoming traffic and the last deployment, each with its source, and keeps the possible causes apart from the facts. Raising the limit from there goes through the resource preview; Orbit then watches for 10 minutes and resolves the incident if no restart follows. Without a fix, an incident resolves after an hour without restarts.</p><h2 id="autoscaling" tabindex="-1">Autoscaling <a class="header-anchor" href="#autoscaling" aria-label="Permalink to &quot;Autoscaling {#autoscaling}&quot;">​</a></h2><p><strong>Scale automatically</strong> in the same Settings makes the instances follow CPU, between a minimum and a maximum.</p><ul><li>Instances are added while their average CPU stays above the target share of the CPU limit, and removed once it has stayed below for 5 minutes.</li><li>The preview reserves memory and CPU for the maximum, so scaling up never runs out of room, and other changes on that server count the maximum too.</li><li>Deployments and resource changes keep the number of instances the autoscaler chose, within the new bounds.</li><li>The service&#39;s metrics show an Instances chart, and the timeline lists each time instances were added or removed with the CPU that led to it.</li><li><strong>Limits:</strong> up to 10 instances, a target between 20% and 95%, and scheduled jobs cannot autoscale. All instances run on the application&#39;s server, so autoscaling handles load, not the loss of that server.</li></ul><p>Under HTTP load on a test cluster, an application went from 1 to 3 instances in under 2 minutes and back to 1 within 10 minutes after the load stopped.</p><h2 id="placement" tabindex="-1">Servers <a class="header-anchor" href="#placement" aria-label="Permalink to &quot;Servers {#placement}&quot;">​</a></h2><p>An application runs on one server by default. With more than one <a href="./servers">server</a>, its Settings has a <strong>Servers</strong> section to move it to another server or spread its instances across several.</p><ul><li><strong>Spreading:</strong> instances are spread evenly, one per server where possible. Autoscaling keeps spreading the ones it adds.</li><li><strong>When a server is lost:</strong> its instances start again on the other servers. On a three-server test cluster this took about a minute and a half, most of it Kubernetes waiting before it declares the server lost. The other instances keep serving meanwhile, but requests the router still sends to the lost ones fail until then: 8 of 71 requests, one per second, in the first 52 seconds of the test.</li><li><strong>The preview</strong> shows how many instances each server would hold at the autoscaling maximum and what stays free, and refuses a server that is not ready, has no room or has another CPU architecture than a built image.</li><li><strong>Surviving a loss:</strong> the preview also simulates losing each chosen server. The others must have room for the instances that would move to them, next to everything already there, including instances of other applications that would move too. If not, it names the server and the missing memory and refuses. Each server then keeps that room, so later changes on it (another application, a database, a resize) cannot take it away, and the Servers page shows how much it keeps.</li><li><strong>Images:</strong> a built image is copied to every chosen server before an instance starts there. Images from a registry are pulled by each server.</li><li><strong>What it does not cover:</strong><ul><li>with one instance, the application stops until that instance starts on another server, so use two or more;</li><li>traffic enters only through the main server unless <a href="./servers#entry">other servers receive it</a>, and even then losing the main server makes the requests sent to its instances fail;</li><li>moving instances needs the cluster&#39;s control plane, which runs only on the main server unless you <a href="./servers#control-plane">run it on three servers</a>.</li></ul></li></ul><h2 id="more-applications" tabindex="-1">More than one application <a class="header-anchor" href="#more-applications" aria-label="Permalink to &quot;More than one application {#more-applications}&quot;">​</a></h2><p>A project can run several applications in the same environment, such as an API and an admin panel. <strong>Add application</strong> under <strong>Good company</strong> opens the same steps as a new project, from a repository or an image. They end with the environment&#39;s databases: each one you pick is connected to the new application as a reference, so two applications can use the same database from their first deployment.</p><h2 id="workers" tabindex="-1">Workers and jobs <a class="header-anchor" href="#workers" aria-label="Permalink to &quot;Workers and jobs {#workers}&quot;">​</a></h2><p>Add a worker or a job from an application&#39;s Overview, under <strong>Good company</strong>. It reuses the application&#39;s source and settings with its own name and start command, in the same environment.</p><ul><li><strong>A worker</strong> has no address. Its deployment fails if it restarts or exits within its first 10 seconds.</li><li><strong>A job</strong> runs on its schedule in UTC, or now with <strong>Run now</strong>. When a run is still going at the next match, that match is skipped. Orbit keeps the last five successful and five failed runs with their output and exit code, and the job shows as degraded while its latest run failed. A new schedule applies on the next deployment.</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cronjobs,jobs,pods</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> job/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ru</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="builds" tabindex="-1">Builds <a class="header-anchor" href="#builds" aria-label="Permalink to &quot;Builds {#builds}&quot;">​</a></h2><ul><li>An application from a repository is built on the server for every deployment of a new commit. Redeploying the same commit with the same settings reuses its image.</li><li>The first build of each stack downloads its base images: expect a few minutes for Next.js or Nuxt and less than a minute for small Go, Python or static sites. Later builds of the same project are faster.</li><li>Builds run on the main server, next to your applications. A Next.js or Nuxt build can use 1.5 GB of memory for a minute or two, so a 2 GB server should not build while it is short on memory.</li><li>Each service keeps its ten most recent images, and the build cache trims itself as the disk fills.</li></ul>`,41)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
